public Artwork [] sortArt()
{ 
for (int i = 0; i < noOfArtworks-1; i++) 
{ 
int max_index = i;  
for (int j = i+1; j < noOfArtworks; j++) // accept j=i; 
{  
  
if(theArtworks[j].getArtworkPrice() > 
theArtworks[max_index].getArtworkPrice()) 
{  
 max_index = j; 
} 
 } 
Artwork temp = theArtworks[max_index];  
theArtworks[max_index] = theArtworks[i]; 
theArtworks[i] = temp;  
}   
Artwork [] expensive = new Artwork[5]; 
for (int i = 0; i < 5; i++)  
{  
expensive[i] = theArtworks[i];  
 } 
return expensive; 
} 
Note: Accept  < theArtworks.length-1 for the outer loop. However, a condition must be 
placed inside the loop to check for the null values in the theArtworks[] to avoid the 
NullPointerException. Allow any name for the getter getArtworkPrice() as long as it returns the 
artworkPrice.
